2 Download and prepare the data with spanishoddata
Download a load of data from Spain!


2.1 Seville case study

# Get OD data for the most recently days
zones &lt;- spod_get_zones(zones = "distr", ver = 2)
valid_dates &lt;- spod_get_valid_dates(2)
recent_dates = tail(valid_dates, 3)

# Identify zones corresponding to Seville
zones_seville &lt;- zones |&gt;
  filter(grepl("^Sevilla distrito", name, ignore.case = TRUE))
mapview::mapview(zones_seville)

# Create a 10km buffer to define the Functional Urban Area (FUA)
zones_seville_fua &lt;- zones[st_buffer(zones_seville, dist = 10000), ]
plot(st_geometry(zones_seville_fua))

# Prepare the location data (centroids) for the flow map
sf::sf_use_s2(FALSE)
locations_seville &lt;- zones_seville_fua |&gt;
  st_transform(crs = 4326) |&gt;
  st_centroid() |&gt;
  st_coordinates() |&gt;
  as.data.frame() |&gt;
  mutate(id = zones_seville_fua$id) |&gt;
  rename(lon = X, lat = Y)

# Uncomment to re-download and process OD data from source
flows &lt;- spod_get(
  type = "origin-destination",
  zones = "districts",
  dates = recent_dates
)

od_data_time &lt;- flows |&gt;
  mutate(time = as.POSIXct(paste0(date, "T", hour, ":00:00"))) |&gt;
  group_by(origin = id_origin, dest = id_destination, time) |&gt;
  summarise(count = sum(n_trips, na.rm = TRUE), .groups = "drop") |&gt;
  collect()

flows_seville_time &lt;- od_data_time |&gt;
  filter(origin %in% zones_seville_fua$id & dest %in% zones_seville_fua$id)

saveRDS(flows_seville_time, "flows_seville_time.rds")
saveRDS(locations_seville, "locations_seville.rds")

# Load precomputed data to keep runtime short for workshop use
if (!file.exists("flows_seville_time.rds")) {
  # If gh is available and authenticated, this may download the file quickly.
  system("gh release download v1 --pattern flows_seville_time.rds")
}

if (!file.exists("flows_seville_time.rds")) {
  download.file(
    "https://github.com/tdscience/dstp/releases/download/v1/flows_seville_time.rds",
    "flows_seville_time.rds"
  )
}

flows_seville_time &lt;- readRDS("flows_seville_time.rds")



2.2 Northern Spain case study: Pamplona to Donostia corridor
As an alternative to Seville, you can explore mobility patterns in Northern Spain, covering the Basque Country and Navarre regions. This area includes the cities of Pamplona (Iruña) and Donostia (San Sebastián), stretches from the French border to the Bay of Biscay coast, and forms a roughly rectangular study area whose east–west extent is longer than its north–south extent.
Rather than filtering by a text pattern (as with Seville), we define the study area geographically with a bounding box and select all districts that intersect it. The province codes in the zone id field can also be used: Navarre = 31, Gipuzkoa = 20, Bizkaia = 48, and Álava = 01.

# Get zones
zones &lt;- spod_get_zones(zones = "distr", ver = 2)
valid_dates &lt;- spod_get_valid_dates(2)
recent_dates = tail(valid_dates, 3)

# Define a geographic bounding box for the Northern Spain study area
# Covers from the coast to south of Pamplona, and from the French border
# westward to include the Pamplona--Donostia corridor
bbox_north &lt;- st_bbox(
  c(xmin = -2.5, ymin = 42.6, xmax = -1.0, ymax = 43.5),
  crs = st_crs(4326)
)
bbox_sf &lt;- st_as_sfc(bbox_north)

# Select zones that intersect the bounding box
sf::sf_use_s2(FALSE)
zones_wgs84 &lt;- st_transform(zones, 4326)
zones_north &lt;- zones_wgs84[st_intersects(zones_wgs84, bbox_sf, sparse = FALSE)[, 1], ]

# Visualise the selected zones
plot(st_geometry(zones_north))

# Prepare location data (centroids) for the flow map
locations_north &lt;- zones_north |&gt;
  st_centroid() |&gt;
  st_coordinates() |&gt;
  as.data.frame() |&gt;
  mutate(id = zones_north$id) |&gt;
  rename(lon = X, lat = Y)

# Download OD data (uncomment to re-download from source)
# flows &lt;- spod_get(
#   type = "origin-destination",
#   zones = "districts",
#   dates = recent_dates
# )
