#   filter(origin %in% zones_north$id & dest %in% zones_north$id)
#
# saveRDS(flows_north_time, "flows_north_time.rds")
# saveRDS(locations_north, "locations_north.rds")

# For workshop use, load precomputed data if available
if (file.exists("flows_north_time.rds")) {
  flows_north_time &lt;- readRDS("flows_north_time.rds")
} else {
  message("Precomputed Northern Spain data not found. Run the download block above.")
}
